import json,hashlib
p='/workspace/recovery/agent319/artifacts/batch479-488.json';d={'pages':[],'units':[],'boundary_notes':[],'review_notes':[]}
def add(n,ar,ru,complete=True,join=False):
 if not d['pages'] or d['pages'][-1]['printed_page']!=n:d['pages'].append(dict(printed_page=n,pdf_leaf=n,witness_status='control_print_visually_read',publisher_footnote_text_imported=False,paragraphs=[]))
 pg=d['pages'][-1];sid=f'v4-p{n:03}-{len(pg["paragraphs"])+1:02}'
 pg['paragraphs'].append(dict(id=sid,ar=ar,sha256=hashlib.sha256(ar.encode()).hexdigest(),witness='uploaded_2019_control_pdf',source_complete=complete))
 if join:
  u=d['units'][-1];u['source_ids'].append(sid);u['printed_pages'].append(n);u['ar']+=' '+ar;u['ru']+=' '+ru
 else:d['units'].append(dict(id=sid+'-ru',source_ids=[sid],printed_pages=[n],ar=ar,ru=ru,draft_status='draft',print_collation='control_image_read',independent_human_review=False))
add(479,'ويستدلّ سبحانه بأسمائه وصفاته على بطلان ما نسب إليه من الأحكام والشرائع الباطلة، وأنّ كماله المقدّس يمنع من شرعها، كقوله: {وَإِذَا فَعَلُوا فَاحِشَةً قَالُوا وَجَدْنَا عَلَيْهَا آبَاءَنَا وَاللَّهُ أَمَرَنَا بِهَا قُلْ إِنَّ اللَّهَ لَا يَأْمُرُ بِالْفَحْشَاءِ أَتَقُولُونَ عَلَى اللَّهِ مَا لَا تَعْلَمُونَ} [الأعراف: 28]، وقوله عقيب ما نهى عنه وحرّمه من الشرك والظلم والفواحش والقول عليه بلا علم: {كُلُّ ذَلِكَ كَانَ سَيِّئُهُ عِنْدَ رَبِّكَ مَكْرُوهًا} [الإسراء: 38]، فأعلمك أنّ ما كان سيّئة في نفسه فهو يكرهه، وكماله يأبى أن يجعله شرعًا له ودينًا. فهو سبحانه يدلّ عباده بأسمائه وصفاته على ما يفعله ويأمر به، ويحبّه ويبغضه، ويثيب عليه ويعاقب عليه؛ ولكن هذه الطريق لا يصل إليها إلّا خاصّة الخاصّة، فلذلك كانت طريق الجمهور الدلالة بالآيات المشاهدة، فإنّها أوسع وأسهل تناولًا، والله سبحانه يفضّل بعض خلقه على بعض، ويرفع درجات من يشاء، وهو العليم الحكيم.','Он, пречистый, доказывает Своими именами и качествами ложность приписываемых Ему решений и ложных установлений и то, что Его святое совершенство исключает их узаконение. Таковы Его слова: {وَإِذَا فَعَلُوا فَاحِشَةً قَالُوا وَجَدْنَا عَلَيْهَا آبَاءَنَا وَاللَّهُ أَمَرَنَا بِهَا قُلْ إِنَّ اللَّهَ لَا يَأْمُرُ بِالْفَحْشَاءِ أَتَقُولُونَ عَلَى اللَّهِ مَا لَا تَعْلَمُونَ} — «Когда они совершают мерзость, то говорят: „Мы застали за этим наших отцов, и Аллах велел нам это“. Скажи: „Аллах не велит совершать мерзость. Неужели вы говорите об Аллахе то, чего не знаете?“» [«Аль-Араф», 7:28]. И Его слова после запрета многобожия, несправедливости, мерзостей и высказываний о Нём без знания: {كُلُّ ذَلِكَ كَانَ سَيِّئُهُ عِنْدَ رَبِّكَ مَكْرُوهًا} — «Всё злое из этого ненавистно твоему Господу» [«Аль-Исра», 17:38]. Он сообщил тебе, что ненавидит то, что дурно само по себе, и Его совершенство не допускает, чтобы Он сделал это Своим законом и религией. Своими именами и качествами Он, пречистый, указывает рабам на то, что делает и велит, что любит и ненавидит, за что награждает и наказывает. Но этого пути достигают лишь избранные из избранных. Поэтому путь большинства — доказательство через зримые знамения: он шире и доступнее. Аллах, пречистый, даёт одним Своим творениям преимущество перед другими и возвышает степенями кого пожелает. Он — Знающий, Мудрый.')
add(479,'فالقرآن العظيم قد اجتمع فيه ما لم يجتمع في غيره، فإنّه هو الدعوة والحجّة، وهو الدليل والمدلول عليه، وهو الشاهد والمشهود له، وهو الحكم والدليل، وهو الدعوى والبيّنة. قال الله تعالى: {أَفَمَنْ كَانَ عَلَى بَيِّنَةٍ مِنْ رَبِّهِ وَيَتْلُوهُ شَاهِدٌ مِنْهُ} [هود: 17] أي من ربّه، وهو القرآن.','В великом Коране соединено то, что не соединено ни в чём ином: он — и призыв, и довод; и доказательство, и доказываемое; и свидетель, и то, в пользу чего свидетельствуют; и решение, и доказательство; и утверждение, и подтверждение. Всевышний Аллах сказал: {أَفَمَنْ كَانَ عَلَى بَيِّنَةٍ مِنْ رَبِّهِ وَيَتْلُوهُ شَاهِدٌ مِنْهُ} — «Разве тот, кто опирается на ясное доказательство от своего Господа, за которым следует свидетель от Него…» [«Худ», 11:17], то есть от его Господа; это Коран.')
add(479,'وقال تعالى لمن طلب آية تدلّ على صدق رسوله: {أَوَلَمْ يَكْفِهِمْ أَنَّا','Всевышний сказал тем, кто потребовал знамение, доказывающее правдивость Его Посланника: {أَوَلَمْ يَكْفِهِمْ أَنَّا',False)
add(480,'أَنْزَلْنَا عَلَيْكَ الْكِتَابَ يُتْلَى عَلَيْهِمْ إِنَّ فِي ذَلِكَ لَرَحْمَةً وَذِكْرَى لِقَوْمٍ يُؤْمِنُونَ قُلْ كَفَى بِاللَّهِ بَيْنِي وَبَيْنَكُمْ شَهِيدًا يَعْلَمُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَالَّذِينَ آمَنُوا بِالْبَاطِلِ وَكَفَرُوا بِاللَّهِ أُولَئِكَ هُمُ الْخَاسِرُونَ} [العنكبوت: 51-52]، فأخبر سبحانه أنّ الكتاب الذي أنزله يكفي من كلّ آية، ففيه الحجّة والدلالة على أنّه من الله سبحانه، أرسل به رسوله، وفيه بيان ما يوجب لمن اتّبعه السعادة، وينجيه من العذاب. ثمّ قال: {قُلْ كَفَى بِاللَّهِ بَيْنِي وَبَيْنَكُمْ شَهِيدًا يَعْلَمُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ}، فإذا كان سبحانه عالمًا بجميع الأشياء كانت شهادته أصدق شهادة وأعدلها، فإنّها شهادة بعلم تامّ، محيط بالمشهود به، فيكون الشاهد به أعدل الشهداء وأصدقهم.','أَنْزَلْنَا عَلَيْكَ الْكِتَابَ يُتْلَى عَلَيْهِمْ إِنَّ فِي ذَلِكَ لَرَحْمَةً وَذِكْرَى لِقَوْمٍ يُؤْمِنُونَ قُلْ كَفَى بِاللَّهِ بَيْنِي وَبَيْنَكُمْ شَهِيدًا يَعْلَمُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ وَالَّذِينَ آمَنُوا بِالْبَاطِلِ وَكَفَرُوا بِاللَّهِ أُولَئِكَ هُمُ الْخَاسِرُونَ} — «Разве им недостаточно того, что Мы ниспослали тебе Писание, которое читается им? Поистине, в этом — милость и напоминание для верующих людей. Скажи: „Достаточно Аллаха свидетелем между мной и вами. Он знает то, что на небесах и на земле. Те же, кто уверовал в ложь и не уверовал в Аллаха, — они потерпевшие убыток“» [«Аль-Анкабут», 29:51–52]. Он, пречистый, сообщил, что ниспосланное Им Писание достаточно вместо любого знамения: оно содержит довод и доказательство того, что оно от Аллаха, пречистого, с ним Он послал Своего Посланника. В нём разъяснено, что обеспечивает следующему ему счастье и спасает от наказания. Затем Он сказал: {قُلْ كَفَى بِاللَّهِ بَيْنِي وَبَيْنَكُمْ شَهِيدًا يَعْلَمُ مَا فِي السَّمَاوَاتِ وَالْأَرْضِ} — «Скажи: достаточно Аллаха свидетелем между мной и вами. Он знает то, что на небесах и на земле». Поскольку Он, пречистый, знает обо всех вещах, Его свидетельство — самое правдивое и справедливое: оно основано на совершенном знании, объемлющем предмет свидетельства. Поэтому Свидетель об этом — самый справедливый и правдивый из свидетелей.',False,True)
add(480,'وهو سبحانه يذكر علمه عند شهادته، وقدرته وملكه عند مجازاته، وحكمته عند خلقه وأمره، ورحمته عند ذكر إرسال رسوله، وحلمه عند ذكر ذنوب عباده ومعاصيهم، وسمعه عند ذكر دعائهم ومسائلهم، وعزّته وعلمه عند قضائه وقدره. فتأمّل ورود أسمائه الحسنى في كتابه، وارتباطها بالخلق والأمر والثواب والعقاب.','Он, пречистый, упоминает Своё знание, когда свидетельствует; Своё могущество и владычество — когда воздаёт; Свою мудрость — когда творит и повелевает; Своё милосердие — когда говорит об отправлении Посланника; Свою выдержку — когда говорит о грехах и ослушании рабов; Свой слух — когда говорит об их мольбах и просьбах; Своё величие и знание — когда решает и предопределяет. Поразмысли же над тем, как Его прекрасные имена встречаются в Его Книге и как они связаны с творением, повелением, наградой и наказанием.')
add(480,'فصل','Раздел')
add(480,'ومن هذا: قوله تعالى: {وَيَقُولُ الَّذِينَ كَفَرُوا لَسْتَ مُرْسَلًا قُلْ كَفَى بِاللَّهِ شَهِيدًا بَيْنِي وَبَيْنَكُمْ وَمَنْ عِنْدَهُ عِلْمُ الْكِتَابِ} [الرعد: 43]، فاستشهد على رسالته بشهادة الله له، ولا بدّ أن تعلم هذه الشهادة، وتقوم بها الحجّة على المكذّبين له.','К этому относятся и слова Всевышнего: {وَيَقُولُ الَّذِينَ كَفَرُوا لَسْتَ مُرْسَلًا قُلْ كَفَى بِاللَّهِ شَهِيدًا بَيْنِي وَبَيْنَكُمْ وَمَنْ عِنْدَهُ عِلْمُ الْكِتَابِ} — «Неверующие говорят: „Ты не посланник“. Скажи: „Достаточно свидетелем между мной и вами Аллаха и того, у кого знание Писания“» [«Ар-Раад», 13:43]. В подтверждение своего посланничества он призвал свидетельство Аллаха в свою пользу. Это свидетельство должно быть известно и служить доводом против отвергающих его.')
add(481,'وكذلك قوله: {قُلْ أَيُّ شَيْءٍ أَكْبَرُ شَهَادَةً قُلِ اللَّهُ شَهِيدٌ بَيْنِي وَبَيْنَكُمْ} [الأنعام: 19]. وكذلك قوله: {لَكِنِ اللَّهُ يَشْهَدُ بِمَا أَنْزَلَ إِلَيْكَ أَنْزَلَهُ بِعِلْمِهِ وَالْمَلَائِكَةُ يَشْهَدُونَ وَكَفَى بِاللَّهِ شَهِيدًا} [النساء: 166]. وكذلك قوله: {يس وَالْقُرْآنِ الْحَكِيمِ إِنَّكَ لَمِنَ الْمُرْسَلِينَ} [يس: 1-3]، وقوله: {تِلْكَ آيَاتُ اللَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّ وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ} [البقرة: 252]، وقوله: {وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُ} [المنافقون: 1]، وقوله: {مُحَمَّدٌ رَسُولُ اللَّهِ} [الفتح: 29]. فهذا كلّه شهادة منه لرسوله، قد أظهرها وبيّنها، وبيّن صحّتها غاية البيان بحيث قطع العذر بينه وبين عباده، وأقام الحجّة عليهم. فكونه سبحانه شاهدًا لرسوله معلوم بسائر أنواع الأدلّة: عقليّها ونقليّها وفطريّها، ضروريّها ونظريّها.','Таковы же Его слова: {قُلْ أَيُّ شَيْءٍ أَكْبَرُ شَهَادَةً قُلِ اللَّهُ شَهِيدٌ بَيْنِي وَبَيْنَكُمْ} — «Скажи: чьё свидетельство величайшее? Скажи: Аллах — свидетель между мной и вами» [«Аль-Анам», 6:19]. И Его слова: {لَكِنِ اللَّهُ يَشْهَدُ بِمَا أَنْزَلَ إِلَيْكَ أَنْزَلَهُ بِعِلْمِهِ وَالْمَلَائِكَةُ يَشْهَدُونَ وَكَفَى بِاللَّهِ شَهِيدًا} — «Но Аллах свидетельствует о ниспосланном тебе: Он ниспослал его со Своим знанием. И ангелы свидетельствуют, и достаточно Аллаха свидетелем» [«Ан-Ниса», 4:166]. И Его слова: {يس وَالْقُرْآنِ الْحَكِيمِ إِنَّكَ لَمِنَ الْمُرْسَلِينَ} — «Йа син. Клянусь мудрым Кораном! Поистине, ты — один из посланников» [«Йа син», 36:1–3]. И слова: {تِلْكَ آيَاتُ اللَّهِ نَتْلُوهَا عَلَيْكَ بِالْحَقِّ وَإِنَّكَ لَمِنَ الْمُرْسَلِينَ} — «Это аяты Аллаха, которые Мы читаем тебе истинно. Поистине, ты — один из посланников» [«Аль-Бакара», 2:252]. И слова: {وَاللَّهُ يَعْلَمُ إِنَّكَ لَرَسُولُهُ} — «Аллах знает, что ты действительно Его Посланник» [«Аль-Мунафикун», 63:1]. И слова: {مُحَمَّدٌ رَسُولُ اللَّهِ} — «Мухаммад — Посланник Аллаха» [«Аль-Фатх», 48:29]. Всё это — Его свидетельство в пользу Своего Посланника. Он явил его, разъяснил и предельно ясно показал его истинность, так что лишил Своих рабов всякого оправдания перед Ним и установил против них довод. Поэтому то, что Он, пречистый, свидетельствует в пользу Своего Посланника, известно посредством всевозможных доказательств: разума, передачи и врождённой природы, непосредственных и полученных рассуждением.')
add(481,'ومن نظر في ذلك وتأمّله علم أنّ الله سبحانه شهد لرسوله أصدق الشهادة وأعدلها وأظهرها، وصدّقه سائر أنواع التصديق بقوله الذي أقام البراهين على صدقه فيه، وبفعله وبإقراره وبما فطر عليه عباده من الإقرار بكمله، وتنزيهه عن القبائح وعمّا لا يليق به. وكلّ وقت يحدث من آياته الدالّة على صدق رسوله ما يقيم به الحجّة، ويزيل به العذر، ويحكم له ولأتباعه بما وعدهم به من العزّ والنجاة والظفر والتأييد، ويحكم على أعدائه ومكذّبيه بما أوعدهم به من الخزي والنكال والعقوبات المعجّلة الدالّة على تحقيق العقوبات المؤجّلة.','Всмотревшийся в это и поразмысливший узнает, что Аллах, пречистый, засвидетельствовал в пользу Своего Посланника самым правдивым, справедливым и явным свидетельством и подтвердил его всеми видами подтверждения: Своим словом, для истинности которого привёл доказательства; Своим действием; Своим одобрением; тем врождённым признанием Его совершенства и непричастности ко всему дурному и неподобающему, с которым Он создал Своих рабов. Непрестанно Он являет знамения правдивости Своего Посланника, которыми устанавливает довод и устраняет оправдание; присуждает ему и его последователям обещанные Им величие, спасение, победу и поддержку, а его врагам и отвергающим его — обещанные им позор, кару и ближайшие наказания, указывающие на неизбежность наказаний отсроченных.')
add(481,'{هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ','{هُوَ الَّذِي أَرْسَلَ رَسُولَهُ بِالْهُدَى وَدِينِ الْحَقِّ لِيُظْهِرَهُ عَلَى الدِّينِ كُلِّهِ',False)
open(p,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
add(482,'وَكَفَى بِاللَّهِ شَهِيدًا} [الفتح: 28]. فظهر ظهورين: ظهورًا بالحجّة والبيان والدلالة، وظهورًا بالنصر والغلبة والتأييد؛ حتّى يظهر على مخالفه ويكون منصورًا.','وَكَفَى بِاللَّهِ شَهِيدًا} — «Он — Тот, Кто послал Своего Посланника с руководством и религией истины, чтобы возвысить её над всякой религией. Достаточно Аллаха свидетелем» [«Аль-Фатх», 48:28]. Он стал явным двумя способами: через довод, разъяснение и доказательство и через помощь, преобладание и поддержку, так что одолевает своего противника и получает победу.',False,True)
add(482,'وقوله: {لَكِنِ اللَّهُ يَشْهَدُ بِمَا أَنْزَلَ إِلَيْكَ أَنْزَلَهُ بِعِلْمِهِ} [النساء: 166]. فما فيه من الخبر عن علم الله الذي لا يعلمه غيره من أعظم الشهادة بأنّه هو الذي أنزله، كما قال في الآية الأخرى: {أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِعَشْرِ سُوَرٍ مِثْلِهِ مُفْتَرَيَاتٍ وَادْعُوا مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللَّهِ إِنْ كُنْتُمْ صَادِقِينَ فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ فَاعْلَمُوا أَنَّمَا أُنْزِلَ بِعِلْمِ اللَّهِ وَأَنْ لَا إِلَهَ إِلَّا هُوَ فَهَلْ أَنْتُمْ مُسْلِمُونَ} [هود: 13-14]. وليس المراد مجرّد الإخبار بأنّه أنزله وهو معلوم له كما يعلم سائر الأشياء، فإنّ كلّ شيء معلوم له من حقّ وباطل. وإنّما المعنى: أنزله مشتملًا على علمه وفيه علمه، فنزوله مشتملًا على علمه هو آية كونه من عنده وأنّه حقّ وصدق. ونظير هذا قوله: {قُلْ أَنْزَلَهُ الَّذِي يَعْلَمُ السِّرَّ فِي السَّمَاوَاتِ وَالْأَرْضِ} [الفرقان: 6] ذكر ذلك سبحانه تكذيبًا وردًّا على من قال: {افْتَرَاهُ} [الفرقان: 4].','Его слова: {لَكِنِ اللَّهُ يَشْهَدُ بِمَا أَنْزَلَ إِلَيْكَ أَنْزَلَهُ بِعِلْمِهِ} — «Но Аллах свидетельствует о ниспосланном тебе: Он ниспослал его со Своим знанием» [«Ан-Ниса», 4:166]. Содержащиеся в нём сообщения из знания Аллаха, которого не знает никто другой, — одно из величайших свидетельств того, что именно Он его ниспослал. В другом аяте Он сказал: {أَمْ يَقُولُونَ افْتَرَاهُ قُلْ فَأْتُوا بِعَشْرِ سُوَرٍ مِثْلِهِ مُفْتَرَيَاتٍ وَادْعُوا مَنِ اسْتَطَعْتُمْ مِنْ دُونِ اللَّهِ إِنْ كُنْتُمْ صَادِقِينَ فَإِلَّمْ يَسْتَجِيبُوا لَكُمْ فَاعْلَمُوا أَنَّمَا أُنْزِلَ بِعِلْمِ اللَّهِ وَأَنْ لَا إِلَهَ إِلَّا هُوَ فَهَلْ أَنْتُمْ مُسْلِمُونَ} — «Или они говорят: „Он выдумал его“? Скажи: „Принесите десять выдуманных сур, подобных ему, и призовите кого сможете помимо Аллаха, если вы правдивы“. Если они не ответят вам, то знайте: он ниспослан со знанием Аллаха и нет божества, кроме Него. Покоритесь ли вы?» [«Худ», 11:13–14]. Имеется в виду не просто сообщение, что Он ниспослал его и знает о нём, как знает об остальных вещах: ведь Ему известна всякая вещь, истинная и ложная. Смысл в том, что Он ниспослал его содержащим Его знание: в нём — Его знание. То, что он нисходит с Его знанием, — знамение того, что он от Него, что он — истина и правда. Подобны этому слова: {قُلْ أَنْزَلَهُ الَّذِي يَعْلَمُ السِّرَّ فِي السَّمَاوَاتِ وَالْأَرْضِ} — «Скажи: его ниспослал Тот, Кто знает тайну на небесах и на земле» [«Аль-Фуркан», 25:6]. Он, пречистый, упомянул это, опровергая и отвергая сказавшего: {افْتَرَاهُ} — «Он выдумал его» [«Аль-Фуркан», 25:4].')
add(482,'فصل','Раздел')
add(482,'ومن شهادته أيضًا: ما أودعه في قلوب عباده من التصديق الجازم، واليقين الثابت، والطمأنينة بكلامه ووحيه؛ فإنّ العادة تحيل حصول ذلك بما هو من أعظم الكذب والافتراء على ربّ العالمين، والإخبار عنه بخلاف ما هو عليه من أسمائه وصفاته. بل ذلك يوقع أعظم الريب والشكّ، وتدفعه الفطر والعقول السليمة، كما تدفع الفطر التي فطر عليها الحيوان الأغذية الخبيثة الضارّة التي لا تغذّي كالأبوال والأنتان. فإنّه سبحانه فطر القلوب','К Его свидетельству относится также то, что Он вложил в сердца Своих рабов: твёрдую убеждённость в истинности Его слова и откровения, непоколебимую уверенность и успокоение ими. Обычный порядок вещей исключает возникновение этого посредством величайшей лжи и клеветы на Господа миров и сообщений о Нём вопреки тому, каковы Его имена и качества. Напротив, такое вызывает величайшие сомнения и подозрения; здоровая врождённая природа и здравый разум отвергают его, подобно тому как природа, с которой созданы живые существа, отвергает скверную, вредную и не питающую пищу — мочу и гниль. Он, пречистый, создал сердца с природой,',False)
add(483,'على قبول الحقّ، والانقياد له، والطمأنينة به، والسكون إليه ومحبّته؛ وفطرها على بغض الكذب والباطل، والنفور عنه، والريبة به، وعدم السكون إليه. ولو بقيت الفطر على حالها لما آثرت على الحقّ سواه، ولما سكنت إلّا إليه، ولا اطمأنّت إلّا به، ولا أحبّت غيره.','принимающей истину, подчиняющейся ей, обретающей в ней уверенность и покой и любящей её; создал их с неприязнью ко лжи и ложному, отвращением к ним, подозрением к ним и отсутствием покоя в них. Если бы врождённая природа оставалась в своём исходном состоянии, она не предпочла бы истине ничего иного, успокаивалась бы лишь ею, находила уверенность лишь в ней и не любила бы ничего другого.',False,True)
add(483,'ولهذا ندب سبحانه عباده إلى تدبّر القرآن، فإنّ كلّ من تدبّره أوجب له تدبّره علمًا ضروريًّا ويقينًا جازمًا: أنّه حقّ وصدق، بل أحقّ كلّ حقّ، وأصدق كلّ صدق؛ وأنّ الذي جاء به أصدق خلق الله، وأبرّهم، وأكملهم علمًا وعملًا ومعرفة. قال تعالى: {أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ وَلَوْ كَانَ مِنْ عِنْدِ غَيْرِ اللَّهِ لَوَجَدُوا فِيهِ اخْتِلَافًا كَثِيرًا} [النساء: 82]. وقال تعالى: {أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا} [محمّد: 24]. فلو رفعت الأقفال عن القلوب لباشرتها حقائق القرآن، واستنارت فيها مصابيح الإيمان، وعلمت علمًا ضروريًّا يكون عندها كسائر الأمور الوجدانيّة من الفرح والألم والحبّ والخوف= أنّه من عند الله، تكلّم به حقًّا، وبلّغه عنه رسوله جبريل إلى رسوله محمّد ﷺ.','Поэтому Он, пречистый, побудил Своих рабов размышлять над Кораном: всякому размышляющему это размышление даёт непосредственное знание и твёрдую уверенность, что он — истина и правда, более того, самая истинная истина и самая правдивая правда; и что принёсший его — самый правдивый из творений Аллаха, самый благочестивый и самый совершенный в знании, делах и познании. Всевышний сказал: {أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ وَلَوْ كَانَ مِنْ عِنْدِ غَيْرِ اللَّهِ لَوَجَدُوا فِيهِ اخْتِلَافًا كَثِيرًا} — «Неужели они не размышляют над Кораном? Если бы он был не от Аллаха, они нашли бы в нём много противоречий» [«Ан-Ниса», 4:82]. И Всевышний сказал: {أَفَلَا يَتَدَبَّرُونَ الْقُرْآنَ أَمْ عَلَى قُلُوبٍ أَقْفَالُهَا} — «Неужели они не размышляют над Кораном? Или на сердцах их замки?» [«Мухаммад», 47:24]. Если бы с сердец сняли замки, истины Корана непосредственно коснулись бы их, в них засияли бы светильники веры и они обрели бы непосредственное знание, подобное другим внутренним переживаниям — радости, боли, любви и страху, — что он от Аллаха, что Он действительно произнёс его и Его посланник Джибриль передал его от Него Его Посланнику Мухаммаду ﷺ.')
add(483,'فهذا الشاهد في القلب من أعظم الشواهد، وبه احتجّ هرقل على أبي سفيان حيث قال له: فهل يرتدّ أحد منهم سخطة لدينه، بعد أن يدخل فيه؟ فقال: لا. فقال له: وكذلك الإيمان إذا خالطت بشاشته القلوب لا يسخطه أحد.','Это свидетельство в сердце — одно из величайших свидетельств. Им Ираклий привёл довод Абу Суфьяну, когда спросил его: «Отступает ли кто-нибудь из них, возненавидев свою религию после вступления в неё?» Тот ответил: «Нет». Тогда он сказал ему: «Такова и вера: когда её отрада смешивается с сердцами, никто не начинает её ненавидеть».')
add(483,'وقد أشار تعالى إلى هذا المعنى بقوله: {بَلْ هُوَ آيَاتٌ بَيِّنَاتٌ فِي صُدُورِ الَّذِينَ أُوتُوا الْعِلْمَ} [العنكبوت: 49]، وقوله: {وَيَرَى الَّذِينَ أُوتُوا الْعِلْمَ الَّذِي','На этот смысл Всевышний указал словами: {بَلْ هُوَ آيَاتٌ بَيِّنَاتٌ فِي صُدُورِ الَّذِينَ أُوتُوا الْعِلْمَ} — «Напротив, это ясные знамения в груди тех, кому даровано знание» [«Аль-Анкабут», 29:49]. И словами: {وَيَرَى الَّذِينَ أُوتُوا الْعِلْمَ الَّذِي',False)
add(484,'أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ هُوَ الْحَقَّ} [سبأ: 6]، وقوله: {أَفَمَنْ يَعْلَمُ أَنَّمَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ الْحَقُّ كَمَنْ هُوَ أَعْمَى} [الرعد: 19]، وقوله: {وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنْزِلَ عَلَيْهِ آيَةٌ مِنْ رَبِّهِ قُلْ إِنَّ اللَّهَ يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي إِلَيْهِ مَنْ أَنَابَ} [الرعد: 27] يعني: أنّ الآية التي يقترحونها لا توجب هداية، بل الله هو الذي يهدي ويضلّ. ثمّ نبّههم على أعظم آية وأجلّها، وهي: طمأنينة قلوب المؤمنين بذكره الذي أنزله، فقال: {الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللَّهِ} أي بكتابه وكلامه {أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ} [الرعد: 28]. فطمأنينة القلوب الصحيحة والفطر السليمة به وسكونها إليه من أعظم الآيات، إذ يستحيل في العادة أن تطمئنّ القلوب وتسكن إلى الكذب والافتراء والباطل.','أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ هُوَ الْحَقَّ} — «Те, кому даровано знание, видят, что ниспосланное тебе от твоего Господа — истина» [«Саба», 34:6]. И словами: {أَفَمَنْ يَعْلَمُ أَنَّمَا أُنْزِلَ إِلَيْكَ مِنْ رَبِّكَ الْحَقُّ كَمَنْ هُوَ أَعْمَى} — «Разве знающий, что ниспосланное тебе от твоего Господа — истина, подобен слепому?» [«Ар-Раад», 13:19]. И словами: {وَيَقُولُ الَّذِينَ كَفَرُوا لَوْلَا أُنْزِلَ عَلَيْهِ آيَةٌ مِنْ رَبِّهِ قُلْ إِنَّ اللَّهَ يُضِلُّ مَنْ يَشَاءُ وَيَهْدِي إِلَيْهِ مَنْ أَنَابَ} — «Неверующие говорят: „Почему ему не ниспослано знамение от его Господа?“ Скажи: „Аллах вводит в заблуждение кого пожелает и ведёт к Себе того, кто обратился“» [«Ар-Раад», 13:27]. То есть требуемое ими знамение не обусловливает наставления: именно Аллах наставляет и вводит в заблуждение. Затем Он обратил их внимание на величайшее и высочайшее знамение — успокоение сердец верующих ниспосланным Им Напоминанием. Он сказал: {الَّذِينَ آمَنُوا وَتَطْمَئِنُّ قُلُوبُهُمْ بِذِكْرِ اللَّهِ} — «Тех, кто уверовал и чьи сердца успокаиваются Напоминанием Аллаха», — то есть Его Книгой и речью. {أَلَا بِذِكْرِ اللَّهِ تَطْمَئِنُّ الْقُلُوبُ} — «Разве не Напоминанием Аллаха успокаиваются сердца?» [«Ар-Раад», 13:28]. Успокоение им здоровых сердец и неповреждённой врождённой природы, обретение в нём покоя — одно из величайших знамений: по обычному порядку вещей невозможно, чтобы сердца обретали уверенность и покой во лжи, клевете и ложном.',False,True)
add(484,'فإن قيل: فلم لا ذكر سبحانه شهادة رسله مع الملائكة، فقال: شهد الله أنّه لا إله إلّا هو والملائكة والرسل، وهم أعظم شهادة من أولي العلم؟','Если спросят: «Почему же Он, пречистый, не упомянул свидетельство Своих посланников вместе с ангелами и не сказал: „Аллах засвидетельствовал, что нет божества, кроме Него, а также ангелы и посланники“, — ведь их свидетельство весомее свидетельства обладателей знания?»')
add(484,'قيل: في ذلك عدّة فوائد:','Ответ таков: в этом несколько полезных смыслов.')
add(484,'أحدها: أنّ أولي العلم أعمّ من الرسل والأنبياء، فيدخلون هم وأتباعهم.','Первый: обладатели знания — понятие более широкое, чем посланники и пророки; оно включает как их, так и их последователей.')
open(p,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
add(485,'وثانيها: أنّ في ذكر أولي العلم في هذه الشهادة وتعليقها بهم ما يدلّ على أنّها من موجبات العلم ومقتضياته، وأنّ كلّ من كان من أولي العلم فإنّه يشهد بهذه الشهادة؛ كما يقال: إذا طلع الهلال وأضح فإنّ كلّ من كان من أهل النظر يراه، وإذا فاحت رائحة ظاهرة وكلّ من كان من أهل الشمّ يشمّ هذه الرائحة، كما قال تعالى: {وَبُرِّزَتِ الْجَحِيمُ لِمَنْ يَرَى} [النازعات: 36]، أي كلّ من له رؤية يراها حينئذ عيانًا. ففي هذا إيذان أنّ من لم يشهد له سبحانه بهذه الشهادة فهو من أعظم الجهّال، وإن علم من أمور الدنيا ما لا يعلمه غيره، فهو من أولي الجهل لا من أولي العلم. وقد بيّنّا أنّه لم يقم بهذه الشهادة، ويؤدّها على وجهها إلّا أتباع الرسل أهل الإثبات، فهم أولو العلم، وسائر من عداهم أولو الجهل وإن وسّعوا القول وأكثروا الجدال.','Второй: упоминание обладателей знания в этом свидетельстве и отнесение его к ним указывают, что оно необходимо следует из знания и требуется им и что всякий обладатель знания произносит это свидетельство. Подобно тому как говорят: если полумесяц взошёл и стал ясно виден, всякий зрячий увидит его; а если распространился явный запах, всякий обладающий обонянием ощутит его. Всевышний сказал: {وَبُرِّزَتِ الْجَحِيمُ لِمَنْ يَرَى} — «И Ад будет явлен всякому видящему» [«Ан-Назиат», 79:36], — то есть всякий, кто способен видеть, тогда увидит его непосредственно. Здесь указано, что не свидетельствующий о Нём, пречистом, этим свидетельством — один из величайших невежд, даже если знает о мирских делах то, чего не знает никто другой: он из обладателей невежества, а не знания. Мы уже разъяснили, что это свидетельство осуществляют и должным образом передают лишь последователи посланников, признающие Его качества. Они — обладатели знания, а все остальные — обладатели невежества, пусть даже пространно рассуждают и много спорят.')
add(485,'ومنها: الشهادة من الله سبحانه لأهل هذه الشهادة أنّهم أولو العلم. فشهادته لهم أعدل وأصدق من شهادة الجهميّة والمعطّلة والفرعونيّة لهم بأنّهم جهّال، وأنّهم حشويّة، وأنّهم مشبّهة، وأنّهم مجسّمة ونوابت ونواصب. فكفاهم شهادة أصدق الصادقين لهم بأنّهم من أولي العلم، إذ شهدوا له بحقيقة ما شهد به لنفسه، من غير تحريف ولا تعطيل، وأثبتوا له حقيقة هذه الشهادة ومضمونها؛ وخصومهم نفوا عنه حقائقها، وأثبتوا له ألفاظها ومجازاتها.','Ещё один смысл: Аллах, пречистый, свидетельствует об обладателях этого свидетельства, что они — обладатели знания. Его свидетельство о них справедливее и правдивее свидетельства джахмитов, отрицающих качества и последователей Фараона, будто они невежды, хашавиты, уподобляющие, придающие телесность, «выскочки» и насибиты. Достаточно им свидетельства Правдивейшего о том, что они — обладатели знания: ведь они засвидетельствовали о Нём в подлинном смысле то, что Он засвидетельствовал о Себе, без искажения и отрицания качеств, и признали за Ним действительность и содержание этого свидетельства. Их же противники отвергли его действительные смыслы, признав за Ним лишь слова и переносные значения.')
add(485,'فصل','Раздел')
add(485,'وفي ضمن هذه الشهادة الإلهيّة: الثناء على أهل العلم الشاهدين بها','Это божественное свидетельство включает восхваление обладателей знания, произносящих его,',False)
add(486,'وتعديلهم. فإنّه سبحانه قرن شهادتهم بشهادته وشهادة ملائكته، واستشهد بهم على أجلّ مشهود به، وجعلهم حجّة على من أنكر هذه الشهادة، كما يحتجّ بالبيّنة على من أنكر الحقّ. فالحجّة قامت بالرسل على الخلق، وهؤلاء نوّاب الرسل وخلفاؤهم في إقامة حجج الله على العباد.','и признание их справедливости. Он, пречистый, сопоставил их свидетельство со Своим свидетельством и свидетельством Своих ангелов, призвал их свидетельствовать о высочайшем предмете свидетельства и сделал их доводом против отрицающих это свидетельство, подобно тому как свидетельским доказательством обосновывают право перед отрицающим его. Посланники установили довод против творения, а эти люди — заместители и преемники посланников в установлении доводов Аллаха против рабов.',False,True)
add(486,'فصل','Раздел')
add(486,'وقد فسّرت شهادة أولي العلم بالإقرار، وفسّرت بالتبيين والإظهار، والصحيح: أنّها تتضمّن الأمرين، فشهادتهم إقرار، وإظهار وإعلام.','Свидетельство обладателей знания толковали как признание, а также как разъяснение и обнародование. Правильно то, что оно включает оба смысла: их свидетельство — признание, обнародование и сообщение.')
add(486,'وهم شهداء الله على الناس يوم القيامة. قال الله تعالى: {وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا} [البقرة: 143]. وقال تعالى: {هُوَ سَمَّاكُمُ الْمُسْلِمِينَ مِنْ قَبْلُ وَفِي هَذَا لِيَكُونَ الرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ} [الحجّ: 78]، فأخبر أنّه جعلهم عدولًا خيارًا، ونوّه بذكرهم قبل أن يوجدهم لما سبق في علمه من اتّخاذه لهم شهداء يشهدون على الأمم يوم القيامة. فمن لم يقم بهذه الشهادة علمًا وعملًا ومعرفة وإقرارًا، ودعوة وتعليمًا وإرشادًا، فليس من شهداء الله. والله المستعان.','Они — свидетели Аллаха о людях в День воскресения. Всевышний Аллах сказал: {وَكَذَلِكَ جَعَلْنَاكُمْ أُمَّةً وَسَطًا لِتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ وَيَكُونَ الرَّسُولُ عَلَيْكُمْ شَهِيدًا} — «Так Мы сделали вас общиной середины, чтобы вы были свидетелями о людях, а Посланник был свидетелем о вас» [«Аль-Бакара», 2:143]. Всевышний сказал: {هُوَ سَمَّاكُمُ الْمُسْلِمِينَ مِنْ قَبْلُ وَفِي هَذَا لِيَكُونَ الرَّسُولُ شَهِيدًا عَلَيْكُمْ وَتَكُونُوا شُهَدَاءَ عَلَى النَّاسِ} — «Он назвал вас мусульманами прежде и в этом, чтобы Посланник был свидетелем о вас, а вы были свидетелями о людях» [«Аль-Хадж», 22:78]. Он сообщил, что сделал их справедливыми и избранными, и возвысил их упоминание ещё до их создания: в Его предшествующем знании уже было, что Он сделает их свидетелями, которые будут свидетельствовать об общинах в День воскресения. Кто не осуществляет это свидетельство в знании, деле, познании, признании, призыве, обучении и наставлении, тот не относится к свидетелям Аллаха. К Аллаху обращаются за помощью.')
add(486,'قوله تعالى: {إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ} [آل عمران: 19] اختلف المفسّرون: هل هو كلام مستأنف، أو داخل في مضمون هذه الشهادة، فهو بعض المشهود به؟','Относительно слов Всевышнего: {إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ} — «Поистине, религия перед Аллахом — ислам» [«Аль Имран», 3:19], — толкователи разошлись: это самостоятельное высказывание или оно входит в содержание данного свидетельства и является частью того, о чём свидетельствуют?')
add(486,'وهذا الاختلاف مبنيّ على القراءتين في كسر «إنّ» وفتحها. فالأكثرون','Это разногласие основано на двух чтениях: с касрой и с фатхой у частицы «инна/анна». Большинство читает',False)
add(487,'على كسرها على الاستئناف، وفتحها الكسائيّ وحده. والوجه: هو الكسر، لأنّ الكلام الذي قبله قد تمّ، فالجملة الثانية مقرّرة مؤكّدة لمضمون ما قبلها. وهذا أبلغ في التقرير، وأذهب في المدح والثناء. ولهذا كان كسر «إنّ» في قوله: {إِنَّا كُنَّا مِنْ قَبْلُ نَدْعُوهُ إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ} [الطور: 28] أحسن من الفتح، وكان الكسر في قول الملبّي: «لبّيك، إنّ الحمد والنعمة لك» أحسن من الفتح.','с касрой, как начало самостоятельной фразы; только аль-Кисаи читает с фатхой. Предпочтительнее касра: предшествующее высказывание уже завершено, а вторая фраза утверждает и подтверждает его содержание. Это сильнее в утверждении и полнее в прославлении и восхвалении. Поэтому чтение частицы «инна» с касрой в словах: {إِنَّا كُنَّا مِنْ قَبْلُ نَدْعُوهُ إِنَّهُ هُوَ الْبَرُّ الرَّحِيمُ} — «Прежде мы взывали к Нему. Поистине, Он — Благостный, Милосердный» [«Ат-Тур», 52:28] — лучше чтения с фатхой. И касра в словах произносящего тальбию: «Вот я перед Тобой! Поистине, хвала и милость принадлежат Тебе», — лучше фатхи.',False,True)
add(487,'وقد ذكر في توجيه قراءة الكسائيّ ثلاثة أوجه:','Для объяснения чтения аль-Кисаи приводили три варианта:')
add(487,'أحدها: أن تكون الشهادة واقعة على الجملتين، فهي واقعة على {إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ} فهو المشهود به، ويكون فتح «أنّه» من قوله {أَنَّهُ لَا إِلَهَ إِلَّا هُوَ} على إسقاط حرف الجرّ، أي لأنّه لا إله إلّا هو، وهذا توجيه الفرّاء. وهذا ضعيف جدًّا، فإنّ المعنى على خلافه، وأنّ المشهود به هو نفس قوله: {أَنَّهُ لَا إِلَهَ إِلَّا هُوَ}، فالمشهود به «أنّ» وما في حيّزها، والعناية إلى هذا صرفت، وبه حصلت. ولكن لهذا القول ـ مع ضعفه ـ وجه، وهو أن يكون المعنى: شهد الله بتوحيده أنّ الدين عنده الإسلام. والإسلام','Первый: свидетельство относится к обеим фразам. Оно относится к словам {إِنَّ الدِّينَ عِنْدَ اللَّهِ الْإِسْلَامُ} — «Поистине, религия перед Аллахом — ислам», — и именно это является предметом свидетельства, а фатха в «аннаху» из слов {أَنَّهُ لَا إِلَهَ إِلَّا هُوَ} — «что нет божества, кроме Него» — объясняется опущенным предлогом: «поскольку нет божества, кроме Него». Таково объяснение аль-Фарры. Оно очень слабое: смысл иной, и предметом свидетельства являются сами слова {أَنَّهُ لَا إِلَهَ إِلَّا هُوَ} — «что нет божества, кроме Него». Предмет свидетельства — частица «анна» и всё, что входит в её область действия; именно на это обращено внимание и это им достигается. Но даже у такого слабого мнения есть возможный смысл: «Аллах засвидетельствовал Своим единством, что религия перед Ним — ислам». Ислам же',False)
open(p,'w').write(json.dumps(d,ensure_ascii=False,indent=2)+'\n')
add(488,'هو توحيده سبحانه، فتضمّنت الشهادة توحيده، وتحقيق دينه أنّه الإسلام لا غيره.','— это признание Его единства, пречистого. Так свидетельство включает признание Его единства и утверждение, что Его религия — именно ислам, а не что-либо другое.',False,True)
add(488,'الوجه الثاني: أن تكون الشهادة واقعة على الجملتين معًا، كلاهما مشهود به، على تقدير حذف الواو وإرادتها. والتقدير: وأنّ الدين عند الله الإسلام، فتكون جملة استغني فيها عن حرف العطف بما تضمّنت من ذكر المعطوف عليه، كما وقع الاستغناء عنها في قوله: {ثَلَاثَةٌ رَابِعُهُمْ كَلْبُهُمْ} و{خَمْسَةٌ سَادِسُهُمْ كَلْبُهُمْ} [الكهف: 22]. فيحسن ذكر الواو وحذفها، كما حذفت هاهنا، وذكرت في قوله: {وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْ} [الكهف: 22].','Второй вариант: свидетельство относится к обеим фразам вместе, обе являются его предметом, при подразумеваемом, но опущенном союзе «ва» — «и». Полный смысл: «И что религия перед Аллахом — ислам». В этой фразе союз не нужен благодаря содержащемуся в ней упоминанию того, к чему она присоединяется. Подобно тому как он не понадобился в словах: {ثَلَاثَةٌ رَابِعُهُمْ كَلْبُهُمْ} — «Трое, четвёртый — их пёс» — и {خَمْسَةٌ سَادِسُهُمْ كَلْبُهُمْ} — «Пятеро, шестой — их пёс» [«Аль-Кахф», 18:22]. Поэтому допустимы и упоминание «ва», и его опущение: здесь он опущен, а в словах {وَيَقُولُونَ سَبْعَةٌ وَثَامِنُهُمْ كَلْبُهُمْ} — «И говорят: семеро, а восьмой — их пёс» [«Аль-Кахф», 18:22] — упомянут.')
add(488,'الوجه الثالث ـ وهو مذهب البصريّين ـ: أن تجعل «أنّ» الثانية بدلًا من الأولى، والتقدير: شهد الله أنّ الدين عند الله الإسلام. وقوله: {أَنَّهُ لَا إِلَهَ إِلَّا هُوَ} توطئة للثانية وتمهيد، ويكون هذا من البدل الذي الثاني فيه نفس الأوّل، فإنّ الدين الذي هو الإسلام عند الله هو: شهادة أن لا إله إلّا الله والقيام بحقّها. ولك أن تجعله على هذا الوجه من باب بدل الاشتمال لأنّ الإسلام يشتمل على التوحيد.','Третий вариант — мнение басрийцев: считать вторую частицу «анна» заменой первой. Полный смысл: «Аллах засвидетельствовал, что религия перед Аллахом — ислам». А Его слова {أَنَّهُ لَا إِلَهَ إِلَّا هُوَ} — «что нет божества, кроме Него» — вводят и подготавливают вторую фразу. Это вид замены, при котором второе совпадает с первым: ведь религия, являющаяся исламом перед Аллахом, — свидетельство, что нет божества, кроме Аллаха, и осуществление его прав. При этом объяснении можно также считать такую замену заменой по включению, поскольку ислам включает единобожие.')
add(488,'فإن قيل: فكان ينبغي على هذه القراءة أن يقول: إنّ الدين عنده الإسلام،','Если спросят: «Но тогда при этом чтении следовало бы сказать: „Религия перед Ним — ислам“,',False)
